new_raw:
theorem t1 : s ∩ t ∪ s ∩ u ⊆ s ∩ (t ∪ u) := by
  rintro x (⟨xs, xt⟩ | ⟨xs, xu⟩)
  · exact {xs, left, exact xt}
  · exact {xs, right, exact xu}

theorem t5 : s ∪ s ∩ t = s := by
  ext s
  simp { t }

